            if k < m and a == p[k]:
                return k + 1
            if k == m:
                return fail
            return fail
        return m, delta
    if op == 'startswith':
        fail = m + 1

        def delta(k, a):
            if k < m and a == p[k]:
                return k + 1
            if k == m:
                return m
            return fail
        return m, delta
    if op == 'endswith':
        def delta(k, a):
            cur = p[:k] + [a]
            best = 0
            top = min(k + 1, m)
            for j in range(top + 1):
                if p[:j] == cur[len(cur) - j:]:
                    best = j
            return best
        return m, delta
    if op == 'contains':
        def delta(k, a):
            if k == m:
                return m
            cur = p[:k] + [a]
            best = 0
            top = min(k + 1, m)
            for j in range(top + 1):
                if p[:j] == cur[len(cur) - j:]:
                    best = j
            return best
        return m, delta
    raise AssertionError(op)


