        if r < 0.6:
            k = rng.randint(0, 3)
            return {'op': 'and', 'args': [gen(d - 1) for _ in range(k)]}
        if r < 0.9:
            k = rng.randint(0, 3)
            return {'op': 'or', 'args': [gen(d - 1) for _ in range(k)]}
        op = rng.choice(['match', 'startswith', 'endswith', 'contains'])
        n = rng.randint(0, min(len(services), 3))
        path = [rng.choice(services) for _ in range(n)] if services else []
        return {'op': op, 'path': path}
    return gen(depth)


def gen_request(rng):
    nserv = rng.randint(0, 4)
    if nserv == 0:
        services = []
    else:
        pool = ['a', 'b', 'c', 'A', 'aa', 'ab', 'β', 'x y', 'q"z']
        services = rng.sample(pool, nserv)
    nrules = rng.randint(0, 4)
    rules = []
    for _ in range(nrules):
        rules.append({'action': rng.choice(['allow', 'drop']),
                      'when': gen_expr(rng, services, rng.randint(0, 3), None)})
    nq = rng.randint(0, 4)
    queries = []
    for _ in range(nq):
        n = rng.randint(0, 4)
        queries.append([rng.choice(services) for _ in range(n)] if services else [])
    return {'services': services, 'rules': rules, 'queries': queries}


def enumerate_words(services, maxlen):
    out = [[]]
    frontier = [[]]
    for _ in range(maxlen):
        nxt = []
        for w in frontier:
            for s in services:
                nxt.append(w + [s])
        out.extend(nxt)
        frontier = nxt
    return out


def check_dfa(request, out):
    services = request['services']
    dfa = out['dfa']
    rows, accept, dist = dfa['next'], dfa['accept'], dfa['distance']
    m = len(rows)
    assert dfa['start'] == 0
    assert isinstance(m, int)
    assert len(accept) == m and len(dist) == m, 'length mismatch'
    for row in rows:
        assert len(row) == len(services), 'row width'
        for t in row:
            assert isinstance(t, int) and 0 <= t < m
    for a in accept:
        assert isinstance(a, bool)
    for d in dist:
        assert d is None or isinstance(d, int)
    # reachability and canonical numbering
    seen = {0}
    order = [0]
    qi = 0
    word_of = {0: []}
    while qi < len(order):
        s = order[qi]
        qi += 1
        for t in rows[s]:
            if t not in seen:
                seen.add(t)
                order.append(t)
                word_of[t] = word_of[s] + [services[rows[s].index(t)]]
    assert len(seen) == m, 'DFA has unreachable states'
    assert order == list(range(m)), 'canonical numbering violated'
    # acceptance vs direct semantics for each state's representative word
    for s in range(m):
        assert accept[s] == ref.predicate(request, word_of[s]), (
            'accept mismatch at state %d word %r' % (s, word_of[s]))
    # acceptance for all words up to a bound
    for w in enumerate_words(services, min(4, max(0, 6 - len(services)))):
        s = 0
        for tok in w:
            s = rows[s][services.index(tok)]
        assert accept[s] == ref.predicate(request, w), 'language mismatch %r' % (w,)
    # distance self-consistency
    back = [[] for _ in range(m)]
    for s in range(m):
        for t in rows[s]:
            back[t].append(s)
    expect = [None] * m
    queue = [s for s in range(m) if accept[s]]
    for s in queue:
        expect[s] = 0
    h = 0
    while h < len(queue):
        s = queue[h]
        h += 1
        for p in back[s]:
            if expect[p] is None:
                expect[p] = expect[s] + 1
                queue.append(p)
    assert expect == dist, 'distance mismatch'
    # minimality (Myhill-Nerode on the exported DFA)
    sigma = len(services)
    diff = set()
    for i in range(m):
        for j in range(i + 1, m):
            if accept[i] != accept[j]:
                diff.add((i, j))
    changed = True
    while changed:
        changed = False
        for i in range(m):
            for j in range(i + 1, m):
                if (i, j) in diff:
                    continue
                for a in range(sigma):
                    x, y = rows[i][a], rows[j][a]
                    if x > y:
                        x, y = y, x
                    if (x, y) in diff:
                        diff.add((i, j))
                        changed = True
                        break
    for i in range(m):
        for j in range(i + 1, m):
            assert (i, j) in diff, 'states %d and %d are equivalent' % (i, j)
    # queries
    for q, res in zip(request['queries'], out['queries']):
        assert set(res) == {'state', 'allow', 'distance'}
        s = 0
        for tok in q:
            s = rows[s][services.index(tok)]
        assert res['state'] == s
        assert res['allow'] is accept[s]
        assert res['distance'] == dist[s]
        assert accept[s] == ref.predicate(request, list(q)), 'query language mismatch'


def run(seed_lo, seed_hi):
    for seed in range(seed_lo, seed_hi):
        rng = random.Random(seed)
        req = gen_request(rng)
        raw = json.dumps(req).encode('utf-8')
        got = impl.process(raw)
        try:
            expected = ref.compile_reference(req)
        except Exception as exc:
            print('reference failed for seed', seed, exc)
            raise
        if expected == 'E_COMPLEXITY':
            assert got == '{"ok":false,"error":"E_COMPLEXITY"}', (seed, got)
            continue
        assert got.endswith('\n'), (seed, got)
        parsed = json.loads(got)
        assert parsed == expected, (seed, req, json.dumps(parsed), json.dumps(expected))
        check_dfa(req, parsed)
    print('ok: seeds %d..%d' % (seed_lo, seed_hi))


if __name__ == '__main__':
    lo = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    hi = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    run(lo, hi)
